	private static readonly Regex InvalidHashtagMatchEnd = new Regex("^(?:[#＃]|://)");

	public static List<string> ParseTags(string str)
	{
		List<string> list = new List<string>();
		try
		{
			if (string.IsNullOrWhiteSpace(str))
			{
				return new List<string>();
			}
			if (!str.Contains("#") && !str.Contains("＃"))
			{
				return new List<string>();
			}
			Match match = ValidHashtag.Match(str);
			while (match.Success)
			{
				string text = str.Substring(match.Index + match.Length);
				str = text;
				if (InvalidHashtagMatchEnd.Match(text).Success)
				{
					continue;
				}
				string tagStr = match.Groups[3].Value;
				if (!string.IsNullOrWhiteSpace(tagStr))
				{
					if (list.FirstOrDefault((string p) => p == tagStr.ToLower()) == null)
					{
						list.Add(tagStr.ToLower());
					}
					match = ValidHashtag.Match(str);
				}
			}
		}
		catch (Exception)
		{
		}
		return list;
	}
